The attributes attached directly to the mounted filesystem fsid kobject
are currently created and removed as part of the broader mounted sysfs
setup.

Factor the main filesystem attributes, the feature group and dynamically
generated unknown feature attributes into dedicated helpers. Keep the
helpers called from the existing mounted sysfs setup and teardown paths for
now. This prepares for adjusting their lifetime separately from the
required subdirectories.

Signed-off-by: Jiacheng Xu <stitch@zju.edu.cn>
---
 fs/btrfs/sysfs.c | 47 +++++++++++++++++++++++++++++++++++------------
 fs/btrfs/sysfs.h |  2 ++
 2 files changed, 37 insertions(+), 12 deletions(-)

diff --git a/fs/btrfs/sysfs.c b/fs/btrfs/sysfs.c
index 0d14570..a89e5ae 100644
--- a/fs/btrfs/sysfs.c
+++ b/fs/btrfs/sysfs.c
@@ -1707,6 +1707,15 @@ static void btrfs_sysfs_remove_fs_devices(struct btrfs_fs_devices *fs_devices)
        }
 }

+void btrfs_sysfs_remove_mounted_attrs(struct btrfs_fs_info *fs_info)
+{
+       struct kobject *fsid_kobj = &fs_info->fs_devices->fsid_kobj;
+
+       addrm_unknown_feature_attrs(fs_info, false);
+       sysfs_remove_group(fsid_kobj, &btrfs_feature_attr_group);
+       sysfs_remove_files(fsid_kobj, btrfs_attrs);
+}
+
 void btrfs_sysfs_remove_mounted(struct btrfs_fs_info *fs_info)
 {
        struct kobject *fsid_kobj = &fs_info->fs_devices->fsid_kobj;
@@ -1730,9 +1739,7 @@ void btrfs_sysfs_remove_mounted(struct btrfs_fs_info *fs_info)
                kobject_put(fs_info->debug_kobj);
        }
 #endif
-       addrm_unknown_feature_attrs(fs_info, false);
-       sysfs_remove_group(fsid_kobj, &btrfs_feature_attr_group);
-       sysfs_remove_files(fsid_kobj, btrfs_attrs);
+       btrfs_sysfs_remove_mounted_attrs(fs_info);
        btrfs_sysfs_remove_fs_devices(fs_info->fs_devices);
 }

@@ -2284,6 +2291,30 @@ int btrfs_sysfs_add_fsid(struct btrfs_fs_devices *fs_devs)
        return 0;
 }

+int btrfs_sysfs_add_mounted_attrs(struct btrfs_fs_info *fs_info)
+{
+       struct kobject *fsid_kobj = &fs_info->fs_devices->fsid_kobj;
+       int ret;
+
+       ret = sysfs_create_files(fsid_kobj, btrfs_attrs);
+       if (ret)
+               return ret;
+
+       ret = sysfs_create_group(fsid_kobj, &btrfs_feature_attr_group);
+       if (ret)
+               goto failure;
+
+       ret = addrm_unknown_feature_attrs(fs_info, true);
+       if (ret)
+               goto failure;
+
+       return 0;
+
+failure:
+       btrfs_sysfs_remove_mounted_attrs(fs_info);
+       return ret;
+}
+
 int btrfs_sysfs_add_mounted(struct btrfs_fs_info *fs_info)
 {
        int ret;
@@ -2294,16 +2325,12 @@ int btrfs_sysfs_add_mounted(struct btrfs_fs_info *fs_info)
        if (ret)
                return ret;

-       ret = sysfs_create_files(fsid_kobj, btrfs_attrs);
+       ret = btrfs_sysfs_add_mounted_attrs(fs_info);
        if (ret) {
                btrfs_sysfs_remove_fs_devices(fs_devs);
                return ret;
        }

-       ret = sysfs_create_group(fsid_kobj, &btrfs_feature_attr_group);
-       if (ret)
-               goto failure;
-
 #ifdef CONFIG_BTRFS_DEBUG
        fs_info->debug_kobj = kobject_create_and_add("debug", fsid_kobj);
        if (!fs_info->debug_kobj) {
@@ -2327,10 +2354,6 @@ int btrfs_sysfs_add_mounted(struct btrfs_fs_info *fs_info)
        if (ret)
                goto failure;

-       ret = addrm_unknown_feature_attrs(fs_info, true);
-       if (ret)
-               goto failure;
-
        ret = sysfs_create_link(fsid_kobj, &fs_info->sb->s_bdi->dev->kobj, "bdi");
        if (ret)
                goto failure;
diff --git a/fs/btrfs/sysfs.h b/fs/btrfs/sysfs.h
index 05498e5..d71438f 100644
--- a/fs/btrfs/sysfs.h
+++ b/fs/btrfs/sysfs.h
@@ -35,6 +35,8 @@ void btrfs_kobject_uevent(struct block_device *bdev, enum kobject_action action)
 int __init btrfs_init_sysfs(void);
 void __cold btrfs_exit_sysfs(void);
 int btrfs_sysfs_add_mounted(struct btrfs_fs_info *fs_info);
+int btrfs_sysfs_add_mounted_attrs(struct btrfs_fs_info *fs_info);
+void btrfs_sysfs_remove_mounted_attrs(struct btrfs_fs_info *fs_info);
 void btrfs_sysfs_remove_mounted(struct btrfs_fs_info *fs_info);
 void btrfs_sysfs_add_block_group_type(struct btrfs_block_group *cache);
 int btrfs_sysfs_add_space_info_type(struct btrfs_space_info *space_info);
